//! Replays the golden corpus generated by
//! `electricity/scripts/generate_decompose_corpus.py` -- real output
//! from Circuitry's own `core/decompose.py` functions -- against this
//! crate's `decompose` module (issue #521).
//!
//! The corpus is checked in (`tests/golden/decompose_corpus.json`);
//! CI separately regenerates it with Python 3.11 and fails the build
//! if it differs (`.github/workflows/electricity-generated.yml`), so
//! this test only needs to trust the committed file.

use electricity_config::{
    ComplexityBand, ComplexitySettings, DecompositionSettings, RoutingSettings,
};
use electricity_value::{Dict, Value};
use electricity_vm::decompose;
use serde::Deserialize;

#[derive(Deserialize, Debug, Clone)]
#[serde(tag = "t")]
enum TaggedValue {
    #[serde(rename = "none")]
    None,
    #[serde(rename = "bool")]
    Bool { v: bool },
    #[serde(rename = "int")]
    Int { v: String },
    #[serde(rename = "float")]
    Float { bits: String },
    #[serde(rename = "str")]
    Str { v: String },
    #[serde(rename = "list")]
    List { v: Vec<TaggedValue> },
    #[serde(rename = "dict")]
    Dict { v: Vec<(TaggedValue, TaggedValue)> },
}

impl From<TaggedValue> for Value {
    fn from(tagged: TaggedValue) -> Self {
        match tagged {
            TaggedValue::None => Value::None,
            TaggedValue::Bool { v } => Value::Bool(v),
            TaggedValue::Int { v } => Value::Int(
                electricity_value::IntValue::parse_decimal(&v).expect("valid decimal integer"),
            ),
            TaggedValue::Float { bits } => {
                let bits = u64::from_str_radix(&bits, 16).expect("valid hex bit pattern");
                Value::Float(f64::from_bits(bits))
            }
            TaggedValue::Str { v } => Value::Str(v),
            TaggedValue::List { v } => Value::List(v.into_iter().map(Value::from).collect()),
            TaggedValue::Dict { v } => {
                let mut dict = Dict::new();
                for (k, val) in v {
                    dict.insert(Value::from(k), Value::from(val));
                }
                Value::Dict(dict)
            }
        }
    }
}

fn band(raw: &serde_json::Value) -> ComplexityBand {
    ComplexityBand {
        model: raw["model"].as_str().unwrap().to_string(),
        max: raw["max"].as_f64(),
        name: raw["name"].as_str().map(str::to_string),
    }
}

// ---------------------------------------------------------------------
// route_up_model
// ---------------------------------------------------------------------

#[derive(Deserialize)]
struct RouteUpModelCase {
    name: String,
    model: Option<String>,
    settings: serde_json::Value,
    expected: Option<String>,
}

#[test]
fn golden_corpus_route_up_model() {
    let corpus = corpus();
    assert!(!corpus.route_up_model_cases.is_empty());
    for case in corpus.route_up_model_cases {
        let settings_raw = &case.settings;
        let bands: Vec<ComplexityBand> = settings_raw["bands"]
            .as_array()
            .unwrap()
            .iter()
            .map(band)
            .collect();
        let settings = ComplexitySettings {
            routing: RoutingSettings {
                enabled: settings_raw["routing_enabled"].as_bool().unwrap(),
                bands,
                respect_explicit: settings_raw["respect_explicit"].as_bool().unwrap(),
            },
            ..ComplexitySettings::default()
        };
        let got = decompose::route_up_model(&settings, case.model.as_deref());
        assert_eq!(got, case.expected, "case {}", case.name);
    }
}

