#[derive(Deserialize)]
struct SourceOutputCase {
    name: String,
    prompt_type: String,
    schema: TaggedValue,
    expected: String,
}

#[test]
fn golden_corpus_source_output() {
    let corpus = corpus();
    assert!(!corpus.source_output_cases.is_empty());
    for case in corpus.source_output_cases {
        let schema = Value::from(case.schema);
        let schema_ref = if schema == Value::None {
            None
        } else {
            Some(&schema)
        };
        let got = decompose::source_output(&case.prompt_type, schema_ref).expect("dump succeeds");
        assert_eq!(got, case.expected, "case {}", case.name);
    }
}

// ---------------------------------------------------------------------
// run_planner -- `planner_input`'s own round trip (the captured
// `initial_state` `_run_isolated` was actually given) and `read_plan`'s
// own round trip (a chosen planner state, read back through the real
// bundled planner's own canonical output paths).
// ---------------------------------------------------------------------

#[derive(Deserialize)]
struct RunPlannerCase {
    name: String,
    source_template: String,
    ctx: TaggedValue,
    prompt_type: String,
    schema: TaggedValue,
    max_chunks: i64,
    returned_state: TaggedValue,
    expected_planner_input: TaggedValue,
    expected_plan_say: TaggedValue,
    expected_plan_chunks: TaggedValue,
    expected_plan_yaml: Option<TaggedValue>,
    expected_plan_done: TaggedValue,
    expected_plan_result_path: String,
}

#[test]
fn golden_corpus_run_planner() {
    let corpus = corpus();
    assert!(!corpus.run_planner_cases.is_empty());
    for case in corpus.run_planner_cases {
        let ctx = Value::from(case.ctx);
        let schema = Value::from(case.schema);
        let schema_ref = if schema == Value::None {
            None
        } else {
            Some(&schema)
        };
        let got_input = decompose::planner_input(
            &case.source_template,
            &ctx,
            &case.prompt_type,
            schema_ref,
            case.max_chunks,
        )
        .expect("planner_input succeeds");
        assert_eq!(
            got_input,
            Value::from(case.expected_planner_input),
            "case {}",
            case.name
        );

        let planner_state = Value::from(case.returned_state);
        let plan = decompose::read_plan(&planner_state);
        assert_eq!(
            plan.say,
            Value::from(case.expected_plan_say),
            "case {} (say)",
            case.name
        );
        assert_eq!(
            plan.chunks,
            Value::from(case.expected_plan_chunks),
            "case {} (chunks)",
            case.name
        );
        let expected_yaml = case.expected_plan_yaml.map(|tagged| {
            Value::from(tagged)
                .as_str()
                .expect("yaml is a str")
                .to_string()
        });
        assert_eq!(plan.yaml, expected_yaml, "case {} (yaml)", case.name);
        assert_eq!(
            plan.done,
            Value::from(case.expected_plan_done),
            "case {} (done)",
            case.name
        );
        assert_eq!(
            plan.result_path, case.expected_plan_result_path,
            "case {} (result_path)",
            case.name
        );
    }
}

// ---------------------------------------------------------------------
// validate_plan
// ---------------------------------------------------------------------

#[derive(Deserialize)]
struct ValidatePlanCase {
    name: String,
    chunks: TaggedValue,
    yaml: Option<TaggedValue>,
    done: TaggedValue,
    result_path: String,
    max_chunks: i64,
    runtime_config: TaggedValue,
    expected: Vec<String>,
    /// Set for the one inline-check case that is a raw PyYAML scan error
    /// (DESIGN.md §1, §12): compared by this fixed prefix and a non-empty
    /// rest only, never `expected`'s own exact wording, which came out of
    /// Python's own (different) scanner.
    #[serde(default)]
    third_party_prefix: Option<String>,
}

#[test]
fn golden_corpus_validate_plan() {
    let corpus = corpus();
    assert!(!corpus.validate_plan_cases.is_empty());
    for case in corpus.validate_plan_cases {
        let yaml = case.yaml.map(|tagged| {
            Value::from(tagged)
                .as_str()
                .expect("yaml tagged value was not a string")
                .to_string()
        });
        let plan = decompose::Plan {
            say: Value::None,
            chunks: Value::from(case.chunks),
            yaml,
            done: Value::from(case.done),
            result_path: case.result_path.clone(),
        };
        let runtime_config = Value::from(case.runtime_config);
        let got = decompose::validate_plan(&plan, case.max_chunks, &runtime_config);
        match &case.third_party_prefix {
            Some(prefix) => {
                assert_eq!(got.len(), 1, "case {}: {got:?}", case.name);
                assert!(
                    got[0].starts_with(prefix.as_str()) && got[0].len() > prefix.len(),
                    "case {}: {:?} does not start with {prefix:?} with a non-empty rest",
                    case.name,
                    got[0]
                );
            }
            None => assert_eq!(got, case.expected, "case {}", case.name),
        }
    }
}

// ---------------------------------------------------------------------
// failure / max_depth / success records
// ---------------------------------------------------------------------

#[derive(Deserialize)]
struct FailureCase {
    name: String,
    score: f64,
    threshold: f64,
    depth: u32,
    max_depth: i64,
    on_failure: String,
    reason: String,
    error: String,
    fallback_model: Option<String>,
    raw_payload: Option<String>,
    expected_meta: TaggedValue,
    expected_fail: bool,
    expected_fallback_model: Option<String>,
}

fn static_reason(reason: &str) -> &'static str {
    match reason {
        "planner_failed" => "planner_failed",
        "invalid_plan" => "invalid_plan",
        "execution_failed" => "execution_failed",
        "max_depth" => "max_depth",
        other => panic!("unknown reason in corpus: {other}"),
    }
}

#[test]
fn golden_corpus_failure_result() {
    let corpus = corpus();
    assert!(!corpus.failure_cases.is_empty());
    for case in corpus.failure_cases {
        let settings = DecompositionSettings {
            threshold: case.threshold,
            max_depth: case.max_depth,
            on_failure: case.on_failure.clone(),
            ..DecompositionSettings::default()
        };
        let base = decompose::base_meta(case.score, &settings, case.depth);
        let result = decompose::failure_result(
            base,
            &settings,
            static_reason(&case.reason),
            case.error.clone(),
            case.fallback_model.clone(),
            case.raw_payload.clone(),
        );
        assert_eq!(
            result.meta,
            Value::from(case.expected_meta),
            "case {}",
            case.name
        );
        let is_fail = case.on_failure == "fail";
        assert_eq!(is_fail, case.expected_fail, "case {}", case.name);
        match result.posture {
            decompose::Posture::Fail { reason, error } => {
                assert!(is_fail, "case {}", case.name);
                assert_eq!(reason, static_reason(&case.reason));
                assert_eq!(error, case.error);
            }
            decompose::Posture::Dispatch { fallback_model } => {
                assert!(!is_fail, "case {}", case.name);
                assert_eq!(
                    fallback_model, case.expected_fallback_model,
                    "case {}",
                    case.name
                );
            }
            decompose::Posture::Decomposed(_) => {
                panic!("case {}: unexpected Decomposed posture", case.name)
            }
        }
    }
}

#[derive(Deserialize)]
struct MaxDepthCase {
    name: String,
    score: f64,
    threshold: f64,
    depth: u32,
    max_depth: i64,
    fallback_model: Option<String>,
    expected_meta: TaggedValue,
}

#[test]
fn golden_corpus_max_depth_result() {
    let corpus = corpus();
    assert!(!corpus.max_depth_cases.is_empty());
    for case in corpus.max_depth_cases {
        let settings = DecompositionSettings {
            threshold: case.threshold,
            max_depth: case.max_depth,
            ..DecompositionSettings::default()
        };
        let base = decompose::base_meta(case.score, &settings, case.depth);
        let result = decompose::max_depth_result(base, case.fallback_model.clone());
        assert_eq!(
            result.meta,
            Value::from(case.expected_meta),
            "case {}",
            case.name
        );
        match result.posture {
            decompose::Posture::Dispatch { fallback_model } => {
                assert_eq!(fallback_model, case.fallback_model, "case {}", case.name)
            }
            other => panic!("case {}: expected Dispatch, got {other:?}", case.name),
        }
    }
}

#[derive(Deserialize)]
struct SuccessCase {
    name: String,
    score: f64,
    threshold: f64,
    depth: u32,
    max_depth: i64,
    plan_say: String,
    plan_chunks: Vec<i64>,
    result_path: String,
    yaml: String,
    expected_meta: TaggedValue,
    expected_key_order: Vec<String>,
}

#[test]
fn golden_corpus_success_result() {
    let corpus = corpus();
    assert!(!corpus.success_cases.is_empty());
    for case in corpus.success_cases {
        let settings = DecompositionSettings {
            threshold: case.threshold,
            max_depth: case.max_depth,
            ..DecompositionSettings::default()
        };
        let mut base = decompose::base_meta(case.score, &settings, case.depth);
        let plan = decompose::Plan {
            say: Value::Str(case.plan_say.clone()),
            chunks: Value::List(case.plan_chunks.iter().map(|n| Value::from(*n)).collect()),
            yaml: Some(case.yaml.clone()),
            done: Value::Bool(true),
            result_path: case.result_path.clone(),
        };
        decompose::with_plan(&mut base, &plan);
        let result = decompose::success_result(base, Value::None);
        assert_eq!(
            result.meta,
            Value::from(case.expected_meta),
            "case {}",
            case.name
        );
        let keys: Vec<String> = result
            .meta
            .as_dict()
            .unwrap()
            .keys()
            .map(|k| k.as_str().unwrap().to_string())
            .collect();
        assert_eq!(keys, case.expected_key_order, "case {}", case.name);
        assert_eq!(result.posture, decompose::Posture::Decomposed(Value::None));
    }
}

