#[derive(Deserialize)]
struct CycleErrorCase {
    name: String,
    yaml: String,
    stack: Vec<String>,
    expected: Option<String>,
}

#[test]
fn golden_corpus_cycle_error() {
    let corpus = corpus();
    assert!(!corpus.cycle_error_cases.is_empty());
    for case in corpus.cycle_error_cases {
        let identity = decompose::plan_identity(&case.yaml);
        let got = decompose::cycle_error("ask", &case.stack, &identity);
        assert_eq!(got, case.expected, "case {}", case.name);
    }
}

