// ---------------------------------------------------------------------

#[derive(Deserialize)]
struct Corpus {
    route_up_model_cases: Vec<RouteUpModelCase>,
    describe_inputs_cases: Vec<DescribeInputsCase>,
    source_output_cases: Vec<SourceOutputCase>,
    run_planner_cases: Vec<RunPlannerCase>,
    validate_plan_cases: Vec<ValidatePlanCase>,
    failure_cases: Vec<FailureCase>,
    max_depth_cases: Vec<MaxDepthCase>,
    success_cases: Vec<SuccessCase>,
    cycle_error_cases: Vec<CycleErrorCase>,
    missing_result_cases: Vec<MissingResultCase>,
    seed_state_cases: Vec<SeedStateCase>,
}

fn corpus() -> Corpus {
    let text = include_str!("golden/decompose_corpus.json");
    serde_json::from_str(text).expect("golden/decompose_corpus.json is valid JSON")
}
